const replacement = {
  title: 'České Kormidlo',
  text: 'Last minute, pobytové a poznávací zájezdy od aktivního affiliate partnera.',
  tag: 'Last minute a zájezdy',
  url: 'https://ehub.cz/system/scripts/click.php?a_aid=6926a50f&a_bid=b880f187',
  image: 'https://doc.ehub.cz/b/3babee44/7ac23a04.jpg'
};

const signature = (node) => {
  if (!(node instanceof Element)) return '';
  const anchor = node.matches('a') ? node : node.closest('a');
  const image = node.matches('img') ? node : node.querySelector?.('img');
  return [
    node.getAttribute('href') || '',
    node.getAttribute('src') || '',
    node.getAttribute('data-id') || '',
    node.getAttribute('data-partner') || '',
    anchor?.getAttribute('href') || '',
    anchor?.getAttribute('aria-label') || '',
    image?.getAttribute('src') || '',
    node.textContent || ''
  ].join(' ');
};

// Název funkce zůstává kvůli návaznosti observeru, ale karta se už nemaže.
// Mrtvá Excursia se na místě přepíše na aktivní affiliate reklamu.
const removeBlocked = (node) => {
  if (!(node instanceof Element)) return;
  const anchor = node.matches('a') ? node : node.closest('a');
  if (!anchor || anchor.dataset.excursiaReplacement === '1') return;
  if (!blocked.test(`${signature(node)} ${signature(anchor)}`)) return;

  anchor.dataset.excursiaReplacement = '1';
  anchor.href = replacement.url;
  anchor.target = '_blank';
  anchor.rel = 'nofollow sponsored noopener noreferrer';
  anchor.setAttribute('aria-label', `Reklama: ${replacement.title}`);
  anchor.classList.remove('is-image-error');

  for (const attr of Array.from(anchor.attributes)) {
    if (['href','class','target','rel','aria-label','style','data-excursia-replacement'].includes(attr.name)) continue;
    if (blocked.test(attr.value || '')) anchor.removeAttribute(attr.name);
  }

  anchor.querySelectorAll('img').forEach((img) => {
    img.src = replacement.image;
    img.alt = replacement.title;
    img.removeAttribute('srcset');
  });

  const label = anchor.querySelector('.promo-label,.article-rail-label,[data-ad-label]');
  if (label) label.textContent = 'REKLAMA';
  const fallback = anchor.querySelector('.article-rail-fallback');
  if (fallback) fallback.textContent = replacement.title;
  const strong = anchor.querySelector('strong');
  if (strong) strong.textContent = replacement.title;
  const small = anchor.querySelector('small');
  if (small) small.textContent = replacement.tag;
  const call = anchor.querySelector(':scope > b');
  if (call) call.textContent = 'Zjistit více →';

  const copy = Array.from(anchor.querySelectorAll(':scope > span')).find((el) =>
    !el.classList.contains('promo-banner') &&
    !el.classList.contains('article-rail-label') &&
    !el.classList.contains('article-rail-tower-picture') &&
    !el.classList.contains('article-rail-fallback') &&
    !el.classList.contains('article-rail-visual')
  );
  if (copy) copy.textContent = replacement.text;

  // Pokud starší typ karty ukrýval název Excursie v nestandardním HTML,
  // přestavíme jen tento jediný anchor; nikdy ne celý reklamní slot.
  if (blocked.test(anchor.textContent || '')) {
    anchor.innerHTML = `<span class="promo-label">REKLAMA</span><strong>${replacement.title}</strong><span>${replacement.text}</span><b>Zjistit více →</b>`;
  }
};
